---@module 'hl'

-- See https://wiki.hyprland.org/Configuring/Keywords/ for more

local mainMod = "SUPER"

-- Example binds, see https://wiki.hyprland.org/Configuring/Binds/ for more

hl.bind(mainMod .. " + " .. "Q", hl.dsp.exec_cmd("ghostty"))

--open the terminal

--bind = $mainMod, Q, exec, alacritty  #open the terminal

hl.bind(mainMod .. " + " .. "X", hl.dsp.window.close())

-- close the active window

hl.bind(mainMod .. " + " .. "O", hl.dsp.exec_cmd("swaylock"))

-- Lock the screen

hl.bind(mainMod .. " + " .. "U", hl.dsp.exec_cmd("wlogout --protocol layer-shell"))

-- show the logout window

hl.bind(mainMod .. " + " .. "SHIFT" .. " + " .. "M", hl.dsp.exit())

-- Exit Hyprland all together no (force quit Hyprland)

hl.bind(mainMod .. " + " .. "E", hl.dsp.exec_cmd("thunar"))

-- Show the graphical file browser

hl.bind(mainMod .. " + " .. "V", hl.dsp.window.float({ action = "toggle" }))

-- Allow a window to float

hl.bind(mainMod .. " + " .. "F", hl.dsp.window.fullscreen({ mode = "fullscreen", action = "toggle" }))

-- Allow a window to float

hl.bind(mainMod .. " + " .. "F5", hl.dsp.window.fullscreen({ mode = "fullscreen", action = "set" }))

hl.bind(mainMod .. " + " .. "F5", hl.dsp.window.float({ action = "toggle" }))

hl.bind(mainMod .. " + " .. "F5", hl.dsp.window.resize({ x = 480, y = 1080 }))

hl.bind(mainMod .. " + " .. "F5", hl.dsp.window.center())

hl.bind(mainMod .. " + " .. "SPACE", hl.dsp.exec_cmd("wofi"))

-- Show the graphicall app launcher

hl.bind(mainMod .. " + " .. "P", hl.dsp.window.pseudo())

-- dwindle

--bind = $mainMod, M, togglesplit, # dwindle

hl.bind(mainMod .. " + " .. "SHIFT + CTRL" .. " + " .. "S", hl.dsp.exec_cmd("~/.config/hypr/scripts/screenshot_copy.sh"))

hl.bind(
	mainMod .. " + " .. "SHIFT + CTRL" .. " + " .. "S",
	hl.dsp.exec_cmd("~/.config/hypr/scripts/screenshot_save.sh")
)

hl.bind(
	mainMod .. " + " .. "CTRL + SHIFT" .. " + " .. "SPACE",
	hl.dsp.exec_cmd("~/.config/hypr/scripts/switch_layout.sh")
)

hl.bind(mainMod .. " + " .. "CTRL + SHIFT" .. " + " .. 7, hl.dsp.exec_cmd("~/.config/hypr/scripts/speaker_toggle.sh"))

hl.bind(mainMod .. " + " .. "W", hl.dsp.exec_cmd("brave"))

--open browser

hl.bind(mainMod .. " + " .. "R", hl.dsp.exec_cmd("obsidian --ozone-platform-hint=auto"))

-- open obsidian

hl.bind(mainMod .. " + " .. "M", hl.dsp.exec_cmd("spotify"))

-- open Spotify

hl.bind(
	"CTRL + SHIFT" .. " + " .. "B",
	hl.dsp.exec_cmd("brave --new-window https://www.bible.com/bible/111/MAT.1.NIV")
)

-- open bible in current browser window

hl.bind("CTRL + SHIFT + ALT" .. " + " .. "E", hl.dsp.exec_cmd("brave --new-window https://chat.openai.com/"))

-- opens chatGPT

hl.bind("CTRL + SHIFT + ALT" .. " + " .. "A", hl.dsp.exec_cmd("brave --new-window https://claude.ai/"))

-- opens Claude

hl.bind("CTRL + SHIFT + ALT" .. " + " .. "L", hl.dsp.exec_cmd("brave --new-window https://linkedin.com/"))

-- opens Claude

hl.bind(mainMod .. " + " .. "SHIFT" .. " + " .. "B", hl.dsp.exec_cmd("killall waybar && waybar"))

