hl.bind(mainMod .. " + " .. "SHIFT" .. " + " .. "E", hl.dsp.exec_cmd("bemoji -t"))

hl.bind("SUPER + CTRL" .. " + " .. "M", hl.dsp.exec_cmd("~/.config/hypr/scripts/qs_manager.sh toggle monitors"))

