hl.bind("SUPER + SHIFT" .. " + " .. "T", hl.dsp.exec_cmd("~/.config/hypr/scripts/qs_manager.sh toggle focustime"))

hl.bind("SUPER + CTRL" .. " + " .. "SPACE", hl.dsp.exec_cmd("~/.config/hypr/scripts/qs_menu.sh"))

hl.bind(mainMod .. " + " .. "Y", hl.dsp.exec_cmd("wl-kbptr -o modes=floating,bisect -o mode_floating.source=detect"))

hl.bind(mainMod .. " + " .. "T", hl.dsp.exec_cmd("wl-kbptr"))

hl.bind("MOD5" .. " + " .. "Q", hl.dsp.exec_cmd("ghostty"))

--open the terminal

hl.bind("MOD5" .. " + " .. "O", hl.dsp.exec_cmd("swaylock"))

-- Lock the screen

hl.bind("MOD5" .. " + " .. "E", hl.dsp.exec_cmd("thunar"))

-- Show the graphical file browser

hl.bind("MOD5" .. " + " .. "V", hl.dsp.window.float({ action = "toggle" }))

-- Allow a window to float

hl.bind("MOD5" .. " + " .. "F", hl.dsp.window.fullscreen({ mode = "fullscreen", action = "toggle" }))

-- Allow a window to float

hl.bind("MOD5" .. " + " .. "SPACE", hl.dsp.exec_cmd("wofi"))

-- Show the graphicall app launcher

hl.bind(mainMod .. " + " .. "O", hl.dsp.exec_cmd("hyprlock"))

-- ROG G15 Strix (2021) Specific binds

hl.bind("code:156", hl.dsp.exec_cmd("rog-control-center"))

-- ASUS Armory crate key

hl.bind("code:211", hl.dsp.exec_cmd("asusctl profile -n; pkill -SIGRTMIN+8 waybar"))

-- Fan Profile key switch between power profiles

hl.bind("code:121", hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SINK@ toggle"))

-- Speaker Mute FN+F1

hl.bind("code:122", hl.dsp.exec_cmd("wpctl set-volume -l 1.0 @DEFAULT_AUDIO_SINK@ 5%-"))

-- Volume lower key

hl.bind("code:123", hl.dsp.exec_cmd("wpctl set-volume -l 1.0 @DEFAULT_AUDIO_SINK@ 5%+"))

-- Volume Higher key

hl.bind("code:239", hl.dsp.exec_cmd("~/.config/hypr/scripts/screenshot_keycode.sh"))

hl.bind("code:232", hl.dsp.exec_cmd("brightnessctl set 1%-"))

-- Screen brightness down FN+F7

hl.bind("code:233", hl.dsp.exec_cmd("brightnessctl set 1%+"))

-- Screen brightness up FN+F8

hl.bind(mainMod .. " + code:232", hl.dsp.exec_cmd("brightnessctl set 100%-"))

-- Screen brightness 100% down

hl.bind(mainMod .. " + code:233", hl.dsp.exec_cmd("brightnessctl set 50%+"))

-- Screen brightness 50% up

hl.bind("code:237", hl.dsp.exec_cmd("brightnessctl -d asus::kbd_backlight set 33%-"))

-- Keyboard brightness down FN+F2

hl.bind("code:238", hl.dsp.exec_cmd("brightnessctl -d asus::kbd_backlight set 33%+"))

-- Keyboard brightnes up FN+F3

hl.bind("code:210", hl.dsp.exec_cmd("asusctl led-mode -n"))

-- Switch keyboard RGB profile FN+F4

hl.bind(mainMod .. " + " .. 1, hl.dsp.focus({ workspace = 1 }))

hl.bind(mainMod .. " + " .. 2, hl.dsp.focus({ workspace = 2 }))

hl.bind(mainMod .. " + " .. 3, hl.dsp.focus({ workspace = 3 }))

hl.bind(mainMod .. " + " .. 4, hl.dsp.focus({ workspace = 4 }))

hl.bind(mainMod .. " + " .. 5, hl.dsp.focus({ workspace = 5 }))

