hl.bind(mainMod .. " + " .. "SHIFT" .. " + " .. "D", hl.dsp.window.move({ workspace = "r+1" }))

hl.bind(mainMod .. " + " .. "SHIFT" .. " + " .. "A", hl.dsp.window.move({ workspace = "r-1" }))

hl.bind("MOD5" .. " + " .. "D", hl.dsp.focus({ workspace = "r+1" }))

-- Move 1 workspace to the right

hl.bind("MOD5" .. " + " .. "A", hl.dsp.focus({ workspace = "r-1" }))

-- Move 1 workspace to the left

-- Move active window to a workspace with mainMod + SHIFT + [0-9]

hl.bind(mainMod .. " + " .. "SHIFT" .. " + " .. 1, hl.dsp.window.move({ workspace = 1 }))

hl.bind(mainMod .. " + " .. "SHIFT" .. " + " .. 2, hl.dsp.window.move({ workspace = 2 }))

